body:
{
  "pains": [
    {
      "id": "pain:cert-gates-the-deal",
      "statement": "A customer we already won told us the contract can't move until we hand over a SOC 2 report, and we don't have one.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "Procurement asks for the report and the deal sits in limbo.",
        "operational": "Revenue that was forecast for this quarter slips two to nine months while a whole audit program gets stood up from nothing.",
        "personal": "The founder is the one explaining to the board and to the buyer why the close date moved, on a thing that has nothing to do with the product."
      },
      "workflow": "Late-stage sales: the security review step in the buyer's procurement flow, after the commercial terms are agreed, when IT Security asks for the report and the AE has nothing to attach in the email.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "First enterprise or health system prospect sends a vendor security review packet", "cites": ["src:4", "src:5"] },
        { "event": "A signed pilot needs to convert to a paid contract and legal or a compliance officer now sits in the path", "cites": ["src:4"] },
        { "event": "A customer's own insurer or downstream requirement forces them to collect reports from vendors", "cites": ["src:3"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "A potential customer has asked for SOC reports and my gut instinct is to simply say no deal.", "cites": ["src:1"] },
            { "situation": "venting", "verbatim": "Every time I've been asked about SOC compliance, it turned out the underlying reason was either insurance or a requirement the customer had", "cites": ["src:3"] },
            { "situation": "to_their_boss", "verbatim": "certification is about sales.", "cites": ["src:9"] }
          ],
          "costs_them": "A deal cycle, and often the quarter. For a small team the audit also eats weeks of the only senior engineering time they have.",
          "fears": "Losing the logo to a competitor who already has the report, and having said no to the deal for a reason the board won't accept.",
          "dream_outcome": "The report exists before the buyer asks, so security review is a file attachment instead of a project."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "If you're an AI healthtech founder trying to convert pilots into paid contracts, your SOC 2 report is one of the first things IT Security asks for during procurement.", "cites": ["src:4"] },
            { "situation": "when_looking", "verbatim": "It's table stakes. You probably used an automation platform to get it done fast because your 12-person team doesn't have a dedicated compliance function.", "cites": ["src:5"] }
          ],
          "costs_them": "Every deal in the pipeline inherits the same block, so forecasting becomes guesswork.",
          "fears": "Being the person who promised a close date that compliance made impossible.",
          "dream_outcome": "Security review stops being a stage in the funnel where deals go to die."
        }
      },
      "segments": ["seg:startup", "seg:scaling", "seg:regulated"],
      "feature_ref": "feat:automated",
      "cites": ["src:1", "src:3", "src:4", "src:5", "src:9"]
    },
    {
      "id": "pain:screenshot-evidence-grind",
      "statement": "Half of my audit prep is taking screenshots of dashboards to prove something a machine already knows.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "Weeks of manually collecting screenshots, exports and logs into a folder for the auditor.",
        "operational": "The same evidence has to be gathered again every period, and versioned, because auditors ask what a policy looked like six months ago.",
        "personal": "It feels performative. The person doing it knows the work produced nothing except a folder."
      },
      "workflow": "Audit fieldwork: pulling console screenshots from AWS, Okta, GitHub and the MDM, exporting audit logs, and dropping them into the auditor's evidence request list, one control at a time.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Auditor sends the evidence request list at the start of fieldwork", "cites": ["src:12", "src:13"] },
        { "event": "Auditor asks for a historical version of a policy or config", "cites": ["src:24"] },
        { "event": "Type II observation window opens and evidence must be captured on a schedule, not once", "cites": ["src:12"] }
      ],
      "who_feels": ["end_user", "champion", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "at the end of the day it's a huge pain grabbing screenshots for what feels like a very performative process.", "cites": ["src:12"] },
            { "situation": "when_it_bites", "verbatim": "Oftentimes evidence is screenshots of the running environment (vomit) or audit logs.", "cites": ["src:13"] }
          ],
          "costs_them": "Days of clicking through consoles, repeated at every audit period, that produce no artifact anyone will ever read again.",
          "fears": "That the screenshot gets rejected on a technicality like a missing timestamp and the whole capture has to be redone.",
          "dream_outcome": "The evidence collects itself from the systems of record and the auditor pulls from one place."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "That evidence needs to be versioned (auditors love asking 'show me this policy as it existed 6 months ago')", "cites": ["src:24"] }
          ],
          "costs_them": "Owning a collection project across every team, chasing people who have real work to do.",
          "fears": "Discovering a gap in the evidence trail after the observation window has closed, when nothing can be fixed retroactively.",
          "dream_outcome": "Walking into fieldwork with the evidence already assembled and timestamped."
        }
      },
      "segments": ["seg:startup", "seg:scaling", "seg:regulated"],
      "feature_ref": "feat:automated",
      "cites": ["src:12", "src:13", "src:24"]
    },
    {
      "id": "pain:audit-interrupts-shipping",
      "statement": "Compliance turned a two-hour change into a three-day process and I still can't tell you what it bought us.",
      "element": "b2b:ease_of_doing_business:decreased_hassles",
      "shape": {
        "surface": "Engineers get pulled off roadmap work for access reviews, policy sign-offs, ticket hygiene and evidence requests.",
        "operational": "Delivery slows across the board because process steps get added to every change, not just the risky ones.",
        "personal": "Engineers who joined to build things feel their motivation drain into procedure, and quietly start avoiding anything compliance touches."
      },
      "workflow": "Day to day engineering: the PR and change management flow in GitHub and Jira, plus the recurring nags for access reviews, policy acceptance and training that land in Slack during a sprint.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "New controls roll out and get applied to every change rather than the ones that matter", "cites": ["src:14"] },
        { "event": "Vulnerability rules force remediation of every CVE regardless of exploitability", "cites": ["src:32"] },
        { "event": "Separation of duties requirements hit a team too small to satisfy them", "cites": ["src:29"] }
      ],
      "who_feels": ["end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "something goes from being done in 2 hours to taking 3+ days.", "cites": ["src:14"] },
            { "situation": "venting", "verbatim": "my main motivator of achieving good outcomes for users, has been derailed by procedure.", "cites": ["src:16"] },
            { "situation": "when_refusing", "verbatim": "the processes are built around having one person who writes code, and another person who reviews the written code. That's obviously impossible as a solo dev.", "cites": ["src:29"] }
          ],
          "costs_them": "Velocity, and the part of the job they actually like.",
          "fears": "That this is permanent, and every future quarter has a compliance tax baked into it.",
          "dream_outcome": "Controls that read the systems they already use instead of adding steps to them."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "venting", "verbatim": "SOC2 - the thing your CTO tells you important but does everything in their power to ignore.", "cites": ["src:15"] },
            { "situation": "when_comparing", "verbatim": "your audit compliance software (something like Vanta.com) is going to be setup to mandate every CVE", "cites": ["src:32"] }
          ],
          "costs_them": "Engineering capacity they have to justify losing, on work with no user-visible output.",
          "fears": "Being the leader who let a compliance program set the engineering roadmap.",
          "dream_outcome": "The audit runs off evidence that already exists, and nobody's sprint changes shape."
        }
      },
      "segments": ["seg:startup", "seg:scaling"],
      "feature_ref": "feat:automated",
      "cites": ["src:14", "src:15", "src:16", "src:29", "src:32"]
    },
    {
      "id": "pain:questionnaire-tax",
      "statement": "Every prospect sends a different spreadsheet of the same questions and wants it back in two days.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Hundreds of near-duplicate questions arrive as a spreadsheet or a portal login, per deal.",
        "operational": "Sales stalls while someone senior enough to answer correctly reads every row, and the answers are never reused.",
        "personal": "The person answering knows most of the questions are irrelevant to their product, and answers them anyway because the deal depends on it."
      },
      "workflow": "Between demo and contract: the buyer's vendor security assessment lands as an XLSX or a portal invite, and gets bounced between sales, engineering and whoever owns security until every row has a defensible answer.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Prospect's security team sends their standard assessment with a short turnaround", "cites": ["src:38"] },
        { "event": "A single unanswerable question threatens to end the evaluation", "cites": ["src:30"] },
        { "event": "Questionnaires arrive on deals too small to justify the effort", "cites": ["src:11", "src:42"] }
      ],
      "who_feels": ["champion", "end_user", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "customer just told you to turn around in 2 days", "cites": ["src:38"] },
            { "situation": "venting", "verbatim": "Having to fill endless security questionnaire without being sure you can even sell", "cites": ["src:37"] },
            { "situation": "when_it_bites", "verbatim": "VSAs were a major pain point for our customers (small to mid market companies trying to sell to enterprises)", "cites": ["src:35"] }
          ],
          "costs_them": "Days of senior time per deal, spent on work that adds nothing to the product or the relationship.",
          "fears": "One wrong or missing answer kills a deal that was already won on merit.",
          "dream_outcome": "Answers get drafted from what the company already documented, and the rep sends it back the same day."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_refusing", "verbatim": "it probably won't be cost-effective for most vendors to gather and collate this documentation", "cites": ["src:11"] },
            { "situation": "venting", "verbatim": "I get these security 'wall of questions' for my $10/lifetime SaaS product", "cites": ["src:42"] },
            { "situation": "when_comparing", "verbatim": "They run anywhere from $250-$4500 each. The main problem is that there has become a race to longer questionnaires", "cites": ["src:34"] }
          ],
          "costs_them": "Either the deal, or a cost per response that eats the margin on small contracts.",
          "fears": "That the questionnaire burden makes the whole mid-market segment unprofitable to sell into.",
          "dream_outcome": "A reusable, current answer library that turns each new questionnaire into a review rather than a rewrite."
        },
        "end_user": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Get even a single NO and you're done", "cites": ["src:30"] },
            { "situation": "venting", "verbatim": "If every customer asked the same questions, such as these, it would be worthwhile compiling answers", "cites": ["src:36"] }
          ],
          "costs_them": "Context switching out of engineering to explain controls to a stranger's spreadsheet.",
          "fears": "Being blamed for an answer that later reads as inaccurate.",
          "dream_outcome": "Never answering the same question twice."
        }
      },
      "segments": ["seg:startup", "seg:scaling", "seg:regulated"],
      "feature_ref": "feat:questionnaire",
      "cites": ["src:11", "src:30", "src:34", "src:35", "src:36", "src:37", "src:38", "src:42"]
    },
    {
      "id": "pain:no-map-of-readiness",
      "statement": "I don't know what has to exist before what, so every decision makes me less sure I'm ready.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "First-timers can't tell what a finished control looks like, or what order policies, evidence and the system description come in.",
        "operational": "Readiness drags for months, work gets redone, and the team discovers late-stage requirements like the system description with no time left.",
        "personal": "A founder or lead who is competent at everything else feels out of their depth and stalls rather than guessing wrong in public."
      },
      "workflow": "Pre-audit readiness: sitting with a control list and a blank policy set, trying to sequence asset inventory, ownership, risk assessment, vendor tracking and evidence before an auditor is even booked.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "First SOC 2 attempt with no prior compliance experience on the team", "cites": ["src:25", "src:24"] },
        { "event": "Discovering the system description narrative near the end of readiness", "cites": ["src:24"] },
        { "event": "Realising the platform's full control list is larger than the business needs", "cites": ["src:21", "src:20"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_looking", "verbatim": "They lack a clear mental model for readiness", "cites": ["src:25"] },
            { "situation": "when_it_bites", "verbatim": "That evidence needs to be versioned (auditors love asking 'show me this policy as it existed 6 months ago')", "cites": ["src:24"] }
          ],
          "costs_them": "Months of calendar time and rework, because the order of operations was learned the expensive way.",
          "fears": "Getting to fieldwork and finding out the foundation was wrong.",
          "dream_outcome": "A sequenced path where each finished step visibly reduces what is left."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_comparing", "verbatim": "Vanta made SOC2 way more intimidating than it was.", "cites": ["src:21"] }
          ],
          "costs_them": "Budget approved against a timeline nobody could estimate.",
          "fears": "Signing up for a program far larger than the deal that triggered it.",
          "dream_outcome": "Knowing on day one what the smallest credible scope is."
        }
      },
      "segments": ["seg:startup"],
      "feature_ref": "feat:automated",
      "cites": ["src:20", "src:21", "src:24", "src:25"]
    },
    {
      "id": "pain:tool-invents-work",
      "statement": "The platform keeps telling me to build things the audit never asked for, and once they're in the report I can't stop doing them.",
      "element": "b2b:ease_of_doing_business:configurability",
      "shape": {
        "surface": "A long list of platform-suggested controls, most of which nobody chose and nobody can switch off.",
        "operational": "Engineering builds capability to satisfy the tool rather than the standard, and stopping later means arguing with the Type II auditor about why a control was dropped.",
        "personal": "The technical lead who advocated for the tool ends up defending work they don't believe in, to their own team."
      },
      "workflow": "Scoping and ongoing monitoring: reviewing the platform's recommended control set and monitoring checks, deciding what to accept, and then living with every accepted item as an audited commitment.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Platform onboarding presents a default control set far wider than the attestation requires", "cites": ["src:18", "src:20"] },
        { "event": "Attempting to retire a control that turned out unnecessary, after it appeared in a Type II", "cites": ["src:19", "src:31"] },
        { "event": "A monitoring rule forces remediation work with no risk rationale behind it", "cites": ["src:32"] }
      ],
      "who_feels": ["technical_evaluator", "blocker"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Vanta will ask (suggest? come perilously close to demand?) you do a lot of engineering work that is absolutely not necessary for a SOC2 attestation.", "cites": ["src:18"] },
            { "situation": "when_comparing", "verbatim": "Most startups should be doing way, way less than automation platforms like these tell them they need to do", "cites": ["src:20"] }
          ],
          "costs_them": "Engineering months spent on controls that were never required, plus a permanent obligation to keep them running.",
          "fears": "Locking the company into a control surface it will still be paying for in three years.",
          "dream_outcome": "Choosing a minimal defensible scope and having the tool respect it."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "If Vanta has you set up some cloud detection capability, and it turns out as you mature your security organization that it wasn't necessary or even useful, you have a fight on your hands with your Type II auditor about why you stopped doing it.", "cites": ["src:19"] },
            { "situation": "when_refusing", "verbatim": "once you do, then it gets set in stone and that's what you are audited against", "cites": ["src:31"] }
          ],
          "costs_them": "Credibility if they wave the purchase through and the team inherits work they warned about.",
          "fears": "Irreversibility. Anything accepted now is a commitment they cannot quietly undo.",
          "dream_outcome": "Scope that can shrink as the security program matures, without an argument with the auditor."
        }
      },
      "segments": ["seg:startup", "seg:scaling"],
      "feature_ref": null,
      "feature_note": "No listed feature addresses this; it is an objection to the category. What would kill it is scope control that is explicit and reversible: a declared minimum control set per framework, and a documented path to retire a control between Type II periods without the auditor treating it as a lapse.",
      "cites": ["src:18", "src:19", "src:20", "src:31", "src:32"]
    },
    {
      "id": "pain:passing-is-not-secure",
      "statement": "We passed the audit and I still can't honestly tell my team we're secure.",
      "element": "b2b:individual:reputational_assurance",
      "shape": {
        "surface": "A clean report sits alongside gaps everyone on the security team knows about.",
        "operational": "Leadership treats the certificate as the security program, so real work loses its case for budget and attention.",
        "personal": "The security lead's professional judgement gets overruled by a document, and their name is on both."
      },
      "workflow": "Post-audit: presenting the report to leadership and to customers while the risk register still has open items the controls never touched.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Leadership reads the clean report as proof the security program is done", "cites": ["src:27", "src:15"] },
        { "event": "A control set is adopted that does not match the actual environment or threat model", "cites": ["src:17", "src:33"] },
        { "event": "A breach elsewhere in the market shows certified vendors failing anyway", "cites": ["src:39"] }
      ],
      "who_feels": ["technical_evaluator", "champion", "blocker"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "venting", "verbatim": "SOC2 is not security. Security is its own thing.", "cites": ["src:17"] },
            { "situation": "when_comparing", "verbatim": "It's incredibly easy to get SOC 2 audited and still have terrible security.", "cites": ["src:22"] },
            { "situation": "venting", "verbatim": "my whole company had a great laugh when a client required us to have a Pandemic Policy in 2019", "cites": ["src:33"] }
          ],
          "costs_them": "Budget and headcount that flow to the attestation instead of to the risks they can name.",
          "fears": "An incident that the report said could not happen, with their signature on the controls.",
          "dream_outcome": "Compliance evidence that is a by-product of a security program they would run anyway."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "We're creating this false sense of security, right?", "cites": ["src:27"] },
            { "situation": "when_it_bites", "verbatim": "Every company you hear about getting hacked had great answers on their security questionnaire", "cites": ["src:39"] }
          ],
          "costs_them": "The standing to argue for anything that isn't on a control list.",
          "fears": "Being the compliance person rather than the security person, in a role they took to do the latter.",
          "dream_outcome": "Controls monitored continuously so the report and reality are the same thing."
        }
      },
      "segments": ["seg:scaling", "seg:regulated"],
      "feature_ref": "feat:grc",
      "cites": ["src:15", "src:17", "src:22", "src:27", "src:33", "src:39"]
    },
    {
      "id": "pain:drift-between-audits",
      "statement": "Between audits I have no idea whether the things we attested to are still true.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "The report is a point-in-time picture assembled from evidence the company chose to hand over.",
        "operational": "Access grants, configs and offboarding drift all year, then get reconstructed in a scramble before the next window.",
        "personal": "The person who signs the representation letter carries a year of quiet uncertainty about what changed under them."
      },
      "workflow": "The eleven months between audits: access grants in Okta and GitHub, cloud config changes, leavers, and new vendors, none of which produce an alert until fieldwork reopens.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:grc",
      "triggers": [
        { "event": "Auditor samples a period and the sample surfaces something nobody was tracking", "cites": ["src:23"] },
        { "event": "Reconstructing a year of evidence in the weeks before fieldwork", "cites": ["src:24", "src:12"] },
        { "event": "A customer asks whether the posture in the report is still current", "cites": ["src:6"] }
      ],
      "who_feels": ["champion", "technical_evaluator"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "Auditors rely on the evidence you provide, so the report can look much cleaner than day to day reality.", "cites": ["src:23"] }
          ],
          "costs_them": "An annual scramble, and a permanent gap between what the report claims and what the lead knows.",
          "fears": "A finding, or worse an incident, in the gap the report never looked at.",
          "dream_outcome": "Knowing the day a control breaks, not the month before the audit."
        }
      },
      "segments": ["seg:scaling", "seg:regulated"],
      "feature_ref": "feat:grc",
      "cites": ["src:6", "src:12", "src:23", "src:24"]
    },
    {
      "id": "pain:proof-is-now-questioned",
      "statement": "Handing over the report isn't enough any more; they want to know who audited us and want to see the evidence.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Buyers ask which audit firm signed the report, which platform produced the evidence, and to see the underlying artifacts.",
        "operational": "Security review gets longer, not shorter, after certification, and buyers call the auditor directly.",
        "personal": "A founder who did the work honestly gets treated as suspect because of what other vendors did."
      },
      "workflow": "Procurement's vendor review step in 2026: the buyer's security team checks the auditor's identity and the provenance of the evidence before accepting the report at all.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Fraudulent SOC 2 attestations in the market make buyers verify the auditor", "cites": ["src:6", "src:8"] },
        { "event": "A reviewer recognises an audit firm they do not trust", "cites": ["src:26"] },
        { "event": "Reports circulate privately, so the buyer cannot tell who failed and switched auditors", "cites": ["src:26"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Now there's a follow-up: 'Which audit firm issued this? Which platform did you use? Can we see the evidence?'", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "Health system IT Security teams don't read vendor summaries and take them at face value. They call the auditor directly.", "cites": ["src:8"] }
          ],
          "costs_them": "Weeks added back onto the cycle the certificate was supposed to shorten.",
          "fears": "Being lumped in with vendors whose reports turned out to be worthless.",
          "dream_outcome": "A public, current posture page the buyer can check themselves, with evidence they can trace."
        },
        "champion": {
          "says": [
            { "situation": "when_comparing", "verbatim": "There are certain auditors that if I see their name on a SOC 2 report, I pretty much throw it in the trash.", "cites": ["src:26"] }
          ],
          "costs_them": "Time re-proving a posture they already proved.",
          "fears": "That their own report gets thrown in someone else's trash for the auditor they picked.",
          "dream_outcome": "Proof that stands on its own without a phone call to the audit firm."
        }
      },
      "segments": ["seg:regulated", "seg:scaling"],
      "feature_ref": "feat:trust",
      "cites": ["src:6", "src:8", "src:26"]
    },
    {
      "id": "pain:vendor-review-backlog",
      "statement": "I'm on the hook for every vendor we onboard, and I can't honestly clear most of them.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "A queue of vendor reviews, each one a report to read and a judgement call to make.",
        "operational": "Reviews become a bottleneck on other teams buying tools, and the reviewer's own controls require the queue be kept current.",
        "personal": "The reviewer knows they are not qualified to judge half of what they are signing off, and signs anyway."
      },
      "workflow": "Vendor onboarding: another team requests a tool, the security or GRC lead reads the vendor's SOC 2 and questionnaire responses, and has to return a verdict without the expertise or the time to truly assess it.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
